{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "The effectiveness of organisational-level workplace mental health interventions on mental health and wellbeing in construction workers: A systematic review and recommended research agenda",
      "reason": "The title explicitly includes the phrase 'A systematic review'."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "The effectiveness of organisational-level workplace mental health interventions on mental health and wellbeing in construction workers: A systematic review and recommended research agenda",
      "reason": "The title identifies the intervention ('organisational-level workplace mental health interventions') and the population ('construction workers')."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The title does not contain supplementary information such as study design or update status, and this is a conditional element that is not required if the information is not present in the title."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_21",
      "quote": "This review identified a low number of studies on this topic with only one study of moderate methodological quality showing a substantial but non-significant decline in sick leave days [73] and no significant effect on general mental health. Results of the remaining 'weak-quality' studies included a significant effect of work redesign in short-term physiological stress parameters... None of the four studies and interventions had an explicit focus on mental health, which may have contributed to the limited evidence for mental health and mental wellbeing in this review.",
      "reason": "The text describes the current state of knowledge (a low number of studies, mostly weak quality) and the uncertainties/limitations regarding the effectiveness of these interventions."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_21",
      "quote": "The evidence found in the four studies was not sufficient to develop specific recommendations for the design of organisational-level mental health promotion programmes in the construction industry and more specifically for SMEs. ... Nevertheless, important lessons can be learned from the review considering the strengths and methodological shortcomings of the four studies to inform a future research agenda for designing and evaluating mental health interventions in the construction industry.",
      "reason": "The text explains the need for the review by highlighting the insufficiency of current evidence to guide practice and the necessity of learning from existing studies to inform a future research agenda."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that this is an update or replication of a specific previous systematic review, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review evaluates a broad category of 'organisational-level workplace mental health interventions' rather than a single specific intervention with a defined mechanism of action, making this requirement not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The authors discuss the need for logic models in future research (chunk text_22), but the review itself does not present a logic model for the interventions being reviewed, nor is it required to do so for this type of broad systematic review."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The specific review questions are: (1) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms, and in enhancing mental wellbeing in construction workers? (2) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms and in enhancing mental wellbeing in SME construction workers?",
      "reason": "The review explicitly states two research questions in the 'Objectives' section."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The specific review questions are: (1) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms, and in enhancing mental wellbeing in construction workers? (2) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms and in enhancing mental wellbeing in SME construction workers?",
      "reason": "The review is an intervention review. The questions clearly define the Population (construction workers/SME construction workers), Intervention (organisational-level mental health programmes), and Outcomes (stress, burnout, non-clinical depressive and anxiety symptoms, mental wellbeing), which constitutes a PICO-like structure."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Table 1. Inclusion and exclusion criteria. ... Population: Construction industry ... Intervention: Organisational-level mental health promotion intervention ... Comparison: Control group Pre- and post-comparison ... Outcomes: Primary: Mental health and wellbeing ... Secondary: Organisational",
      "reason": "The manuscript provides a detailed table (Table 1) specifying inclusion and exclusion criteria for population, intervention, comparison, and outcomes. Additionally, text in chunk_id 'text_13' specifies eligible study designs (RCTs, cRCTs, non-randomised controlled trials, uncontrolled before- and after- designs, and uncontrolled quasi-experimental designs) and chunk_id 'text_3' specifies the publication date range (2010-2022)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Eligibility criteria were randomized controlled trials (RCTs), cluster randomized controlled trials (cRCTs), controlled or uncontrolled before- and after studies published in peer-reviewed journals between 2010 and May 2022 in five databases",
      "reason": "The manuscript specifies the publication date range (2010-2022) and publication status (peer-reviewed journals) in the Methods section. Chunk_id 'text_12' further clarifies that studies were included if published in English."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report distinguishing between exclusion due to outcomes not being measured versus outcome results not being reported; this is a conditional requirement that does not apply as the authors did not report this specific distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Quality appraisal was conducted using the QATQS scale, a narrative synthesis was applied.",
      "reason": "The manuscript states that a narrative synthesis was applied, but it does not explicitly specify how studies were grouped for these syntheses (e.g., by intervention type, population, or outcome). While the results section discusses studies by intervention type, the methods section lacks a clear description of the grouping strategy for synthesis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "In a staged approach only studies with a control group and with a before- and at least one after measurement post intervention were deemed eligible in the first round of selection as they provide the most robust evidence.",
      "reason": "The authors provide a rationale for the staged approach to study eligibility, noting that studies with control groups and before-after measurements were prioritized because they provide the most robust evidence."
    }
  ],
  "confidence": 95
}

